WITH scored AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, NTILE(4) OVER (PARTITION BY account_id ORDER BY amount, id) amount_bucket, AVG(amount) OVER w_hist amount_avg_2_prior, SUM(amount) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_amount FROM transactions WINDOW w_hist AS (PARTITION BY YEAR(txn_time), txn_type ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING)) SELECT id, amount, txn_time, merchant, is_flagged, amount_avg_2_prior, cumulative_amount, CASE WHEN merchant RLIKE '^(Shell|Starbucks)$' THEN 'EXTENDED' ELSE 'CORE' END AS merchant_zone FROM scored
